## 4b: office_generator.suites() on plans written by hand (no floor drawn):
## which room becomes the secretary's, that the lock goes with it, that a
## merged pair is no door, that a director's office may swap, and that no
## secretary loses the director's office it has. 4B_SUITES lines and
## 4B_SUITES_RESULT.
const GEN := preload('res://game/world/generation/office_generator.gd')
const OFFICE := preload('res://game/floors/palettes/office_palette.gd')
var passed := 0
var failed := 0

func check(title: String, ok: bool, detail := '') -> void:
	if ok: passed += 1
	else: failed += 1
	print('4B_SUITES %s %s%s' % ['PASS' if ok else 'FAIL', title, '' if ok else '  (' + detail + ')'])

## A plan of the third planta: rooms of these types, doors on these edges.
static func plan(types: Array, edges: Array) -> Dictionary:
	var rooms: Array = []
	for k in types.size(): rooms.append({'id': k, 'type': int(types[k]), 'corridor': int(types[k]) == OFFICE.CORRIDOR, 'hall': -1, 'service': false, 'wing': 2})
	return {'rooms': rooms, 'edges': edges, 'merged': {}}

static func types_of(f: Dictionary) -> Array:
	return f.rooms.map(func(r): return int(r.type))

func _initialize() -> void:
	var gen = GEN.new()
	var sec: int = OFFICE.SECRETARY
	var exe: int = OFFICE.EXEC_OFFICE
	var store: int = OFFICE.STORE
	var rest: int = OFFICE.BREAK_ROOM
	var hall: int = OFFICE.CORRIDOR
	var one := plan([sec, store, exe, rest], [[0, 1], [1, 2], [2, 3]])
	var locked := {0: true}
	gen.suites(one, locked)
	check('La secretaría cambia con la sala más baja que da a dirección', types_of(one) == [store, sec, exe, rest], str(types_of(one)))
	check('El bloqueo pasa a la sala nueva', locked.has(1) and not locked.has(0), str(locked))
	var two := plan([sec, store, exe, rest], [[0, 1], [1, 2], [2, 3]])
	two.merged[gen.pair_key(1, 2)] = true
	gen.suites(two, {})
	check('Un par fundido en salón no es puerta: cambia con la otra', types_of(two) == [rest, store, exe, sec], str(types_of(two)))
	var three := plan([sec, hall, exe, exe], [[0, 1], [1, 2], [2, 3]])
	gen.suites(three, {})
	check('Sin sala corriente, cambia con un despacho de dirección que da a otro', types_of(three) == [exe, hall, sec, exe], str(types_of(three)))
	var four := plan([sec, hall, exe, exe], [[0, 1], [1, 2], [2, 3]])
	gen.suites(four, {2: true, 3: true})
	check('Con los de dirección bloqueados no cambia nada', types_of(four) == [sec, hall, exe, exe], str(types_of(four)))
	var five := plan([sec, exe, exe, sec, hall], [[0, 1], [1, 2], [3, 4]])
	gen.suites(five, {})
	check('No se quita su despacho de dirección a una secretaría que ya lo tiene', types_of(five) == [sec, exe, sec, exe, hall], str(types_of(five)))
	var six := plan([sec, exe, store], [[0, 1], [1, 2]])
	gen.suites(six, {})
	check('Una secretaría que ya da a dirección se queda', types_of(six) == [sec, exe, store], str(types_of(six)))
	print('4B_SUITES_RESULT %d/%d' % [passed, passed + failed])
